{

"workflow": {
  "title": "vendor onboarding for small manufacturing company",
  "summary": "procurement employee submits supplier request; ai assistant reviews against approved list; procurement manager and finance verify details; final decision creates onboarding record without order placement"
},
"evidence": [
  {"id": "ev-1", "quote": "A procurement employee submits a supplier request with a quotation, company details and a proposed order value."},
  {"id": "ev-2", "quote": "An AI assistant reads the quotation and supplier record, compares the request with the approved supplier list, and prepares a recommendation."},
  {"id": "ev-3", "quote": "The procurement manager reviews the recommendation."},
  {"id": "ev-4", "quote": "Finance verifies bank details through a separate established channel."},
  {"id": "ev-5", "quote": "Only an authorised procurement employee can add a vendor to the purchasing system."},
  {"id": "ev-6", "quote": "Requests involving missing or conflicting records are paused for review."},
  {"id": "ev-7", "quote": "The expected benefit is less time spent preparing each review."}
],
"facts": [
  {"id": "fact-1", "evidence_ids": ["ev-1","ev-2","ev-3","ev-4","ev-5","ev-6","ev-7"]},
  {"id": "fact-2", "evidence_ids": ["ev-2","ev-5"]}
],
"assumptions": [
  {"id": "asm-1", "statement": "AI assistant's comparison of supplier records with approved list is accurate and complete.", "rationale": "ev-2"},
  {"id": "asm-2", "statement": "Procurement manager's review is sufficient to validate recommendation.", "rationale": "ev-3"}
],
"actors": [
  {"id": "actor-procurement-employee", "label": "Procurement Employee", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-1","ev-5"]},
  {"id": "actor-ai-assistant", "label": "AI Assistant", "kind": "ai", "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"id": "actor-procurement-manager", "label": "Procurement Manager", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-3"]},
  {"id": "actor-finance", "label": "Finance", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-4"]}
],
"data": [
  {"id": "data-supplier-request", "label": "Supplier Request", "description": "Includes quotation, company details, and proposed order value", "classification": "unknown", "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"id": "data-approved-supplier-list", "label": "Approved Supplier List", "description": "Pre-approved vendors for comparison", "classification": "unknown", "source_state": "stated", "evidence_ids": ["ev-2"]}
],
"tools": [
  {"id": "tool-ai-assistant", "label": "AI Assistant", "purpose": "Compare supplier records with approved list", "mode": "read", "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"id": "tool-purchasing-system", "label": "Purchasing System", "purpose": "Vendor addition and order management", "mode": "read", "source_state": "stated", "evidence_ids": ["ev-5"]}
],
"steps": [
  {"id": "step-1", "label": "Supplier Request Submission", "description": "Procurement employee submits request with quotation and details", "actor_ids": ["actor-procurement-employee"], "input_data_ids": ["data-supplier-request"], "output_data_ids": ["data-supplier-request"], "tool_ids": ["tool-ai-assistant"], "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"id": "step-2", "label": "AI Recommendation", "description": "AI compares request with approved list and prepares recommendation", "actor_ids": ["actor-ai-assistant"], "input_data_ids": ["data-supplier-request","data-approved-supplier-list"], "output_data_ids": ["data-supplier-request"], "tool_ids": ["tool-ai-assistant"], "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"id": "step-3", "label": "Procurement Manager Review", "description": "Manager reviews AI recommendation for approval", "actor_ids": ["actor-procurement-manager"], "input_data_ids": ["data-supplier-request"], "output_data_ids": ["data-supplier-request"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-3"]},
  {"id": "step-4", "label": "Finance Verification", "description": "Finance checks bank details through established channel", "actor_ids": ["actor-finance"], "input_data_ids": ["data-supplier-request"], "output_data_ids": ["data-supplier-request"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-4"]},
  {"id": "step-5", "label": "Final Decision", "description": "Acceptance creates onboarding record; rejection returns request", "actor_ids": ["actor-procurement-employee"], "input_data_ids": ["data-supplier-request"], "output_data_ids": ["data-supplier-request"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-6"]}
],
"decisions": [
  {"id": "decision-ai-recommendation", "step_id": "step-2", "question": "Should the supplier be recommended based on approved list match?", "criteria": ["ev-2"], "authority_actor_ids": ["actor-ai-assistant"], "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"id": "decision-manager-approval", "step_id": "step-3", "question": "Should the recommendation be approved for onboarding?", "criteria": ["ev-3"], "authority_actor_ids": ["actor-procurement-manager"], "source_state": "stated", "evidence_ids": ["ev-3"]},
  {"id": "decision-finance-verification", "step_id": "step-4", "question": "Are bank details valid and verified?", "criteria": ["ev-4"], "authority_actor_ids": ["actor-finance"], "source_state": "stated", "evidence_ids": ["ev-4"]}
],
"edges": [
  {"from_step_id": "step-1", "to_step_id": "step-2", "condition": "request submitted", "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"from_step_id": "step-2", "to_step_id": "step-3", "condition": "recommendation prepared", "source_state": "stated", "evidence_ids": ["ev-2"]},
  {"from_step_id": "step-3", "to_step_id": "step-4", "condition": "manager approval", "source_state": "stated", "evidence_ids": ["ev-3"]},
  {"from_step_id": "step-4", "to_step_id": "step-5", "condition": "verification complete", "source_state": "stated", "evidence_ids": ["ev-4"]},
  {"from_step_id": "step-2", "to_step_id": "step-5", "condition": "conflicting records", "source_state": "stated", "evidence_ids": ["ev-6"]}
],
"requirements": [
  {"id": "req-1", "statement": "Procurement employee must submit complete supplier request", "kind": "policy", "source_state": "stated", "evidence_ids": ["ev-1"]},
  {"id": "req-2", "statement": "AI assistant must compare against approved supplier list", "kind": "policy", "source_state": "stated", "evidence_ids": ["ev-2"]}
],
"existing_controls": [
  {"id": "existing-1", "description": "AI assistant cannot modify vendor records or place orders", "step_ids": ["step-2"], "source_state": "stated", "evidence_ids": ["ev-2","ev-5"]},
  {"id": "existing-2", "description": "Only authorised procurement employee can add vendor", "step_ids": ["step-5"], "source_state": "stated", "evidence_ids": ["ev-5"]}
],
"risks": [
  {"id": "risk-1", "title": "AI Misclassification", "scenario": "AI incorrectly recommends unapproved supplier", "impact": "Potential vendor fraud", "step_ids": ["step-2"], "data_ids": ["data-approved-supplier-list"], "evidence_ids": ["ev-2"], "uncertainty": "asm-1", "proposed_priority": "high"},
  {"id": "risk-2", "title": "Manager Oversight", "scenario": "Procurement manager approves flawed recommendation", "impact": "Invalid vendor onboarding", "step_ids": ["step-3"], "data_ids": ["data-supplier-request"], "evidence_ids": ["ev-3"], "uncertainty": "asm-2", "proposed_priority": "medium"},
  {"id": "risk-3", "title": "Finance Verification Failure", "scenario": "Bank details not verified properly", "impact": "Payment fraud or failed transactions", "step_ids": ["step-4"], "data_ids": ["data-supplier-request"], "evidence_ids": ["ev-4"], "uncertainty": "unknown", "proposed_priority": "high"}
],
"controls": [
  {"id": "ctrl-1", "family": "data_quality", "recommendation": "AI must validate supplier against approved list", "enforcement_point": "step-2", "risk_ids": ["risk-1"], "step_ids": ["step-2"], "owner_actor_ids": ["actor-procurement-manager"], "validation": "submit altered quotation; expect denial or hold, verify no vendor addition"},
  {"id": "ctrl-2", "family": "human_approval", "recommendation": "Procurement manager must review AI recommendation", "enforcement_point": "step-3", "risk_ids": ["risk-2"], "step_ids": ["step-3"], "owner_actor_ids": ["actor-procurement-manager"], "validation": "submit conflicting records; expect pause for review"},
  {"id": "ctrl-3", "family": "data_quality", "recommendation": "Finance must verify bank details through established channel", "enforcement_point": "step-4", "risk_ids": ["risk-3"], "step_ids": ["step-4"], "owner_actor_ids": ["actor-finance"], "validation": "submit altered bank details; expect verification failure"}
],
"gaps": [
  {"id": "gap-1", "description": "Exact products and API permissions for purchasing system are undefined", "related_ids": ["tool-purchasing-system"], "question_ids": ["question-1"], "blocking": true}
],
"questions": [
  {"id": "question-1", "question": "What are the exact products and API permissions for the purchasing system?", "related_ids": ["gap-1"], "blocking": true},
  {"id": "question-2", "question": "What operating countries and document retention periods are required?", "related_ids": ["gap-1"], "blocking": true},
  {"id": "question-3", "question": "Who will own the onboarding records and what are the budget thresholds?", "related_ids": ["gap-1"], "blocking": true}
],
"human_authority": {
  "accountable_actor_ids": ["actor-procurement-manager","actor-finance"],
  "reviewer_actor_ids": ["actor-procurement-manager","actor-finance"],
  "approval_points": [
    {"step_id": "step-3", "recommended_actor_ids": ["actor-procurement-manager"], "reason": "manager must approve recommendation", "control_ids": ["ctrl-2"]},
    {"step_id": "step-4", "recommended_actor_ids": ["actor-finance"], "reason": "finance must verify bank details", "control_ids": ["ctrl-3"]}
  ],
  "escalation": "unknown"
}
}
